package com.cocode.measureapp.ui.capture

import android.content.Context
import android.hardware.camera2.CameraCharacteristics
import android.hardware.camera2.CameraManager
import androidx.camera.core.ImageCapture
import androidx.camera.core.ImageCaptureException
import androidx.camera.core.ImageProxy
import androidx.core.content.ContextCompat
import com.cocode.measureapp.capture.GravityProvider
import com.cocode.measureapp.capture.recovery.CalibrationQuality
import com.cocode.measureapp.capture.recovery.CaptureMetadata
import com.cocode.measureapp.capture.recovery.CaptureOutcome
import com.cocode.measureapp.capture.recovery.CropRect
import com.cocode.measureapp.capture.recovery.consumeFrame
import com.cocode.measureapp.capture.recovery.exposureTimestampOf
import com.cocode.measureapp.model.CapturedScene
import com.cocode.measureapp.ui.CapturedImage
import com.cocode.measureapp.ui.readIntrinsics
import java.util.concurrent.Executor

/** User-facing message for a camera-reported capture error. */
internal const val CAMERA_ERROR = "Capture failed. Check the camera and try again."

/**
 * Fires one CameraX capture for [requestId]. Exactly one outcome is posted to [onOutcome] on
 * the main thread; the acquired proxy is closed on every path. Synchronous start failures
 * propagate to the caller ([com.cocode.measureapp.capture.recovery.CaptureController.launch]).
 */
internal fun startCapture(
    context: Context,
    imageCapture: ImageCapture,
    executor: Executor,
    requestId: Int,
    cameraId: String?,
    gravity: GravityProvider,
    onOutcome: (Int, CaptureOutcome<CapturedImage>) -> Unit,
) {
    val main = ContextCompat.getMainExecutor(context)
    imageCapture.takePicture(executor, object : ImageCapture.OnImageCapturedCallback() {
        override fun onCaptureSuccess(image: ImageProxy) {
            val outcome = consumeFrame(image) { buildCapturedImage(context, image, requestId, cameraId, gravity) }
            main.execute { onOutcome(requestId, outcome) }
        }

        override fun onError(exception: ImageCaptureException) {
            main.execute { onOutcome(requestId, CaptureOutcome.Failure(CAMERA_ERROR, exception)) }
        }
    })
}

/** Copies all shot metadata from [image] before conversion; the caller closes the proxy. */
@Suppress("DEPRECATION")
private fun buildCapturedImage(
    context: Context,
    image: ImageProxy,
    requestId: Int,
    cameraId: String?,
    gravity: GravityProvider,
): CapturedImage {
    val chars = characteristicsOrNull(context, cameraId)
    val crop = image.cropRect
    val metadata = CaptureMetadata(
        requestId = requestId,
        frameWidth = image.width,
        frameHeight = image.height,
        rotationDegrees = image.imageInfo.rotationDegrees,
        crop = CropRect(crop.left, crop.top, crop.right, crop.bottom),
        exposure = exposureTimestampOf(
            image.imageInfo.timestamp,
            chars?.get(CameraCharacteristics.SENSOR_INFO_TIMESTAMP_SOURCE),
        ),
        gravity = gravity.latestSample(),
        recentGravity = gravity.recentSamples(),
        calibration = if (chars?.get(CameraCharacteristics.LENS_INTRINSIC_CALIBRATION) != null) {
            CalibrationQuality.DEVICE_CALIBRATED
        } else {
            CalibrationQuality.APPROXIMATE
        },
    )
    val bitmap = image.toBitmap()
    try {
        metadata.requireComplete(bitmap.width, bitmap.height)
        val intrinsics = readIntrinsics(context, cameraId, bitmap.width, bitmap.height)
        val scene = CapturedScene(bitmap.width, bitmap.height, intrinsics, gravity.current())
        return CapturedImage(bitmap, scene, metadata)
    } catch (e: Throwable) {
        bitmap.recycle()
        throw e
    }
}

private fun characteristicsOrNull(context: Context, cameraId: String?): CameraCharacteristics? {
    if (cameraId == null) return null
    val cm = context.getSystemService(Context.CAMERA_SERVICE) as CameraManager
    return runCatching { cm.getCameraCharacteristics(cameraId) }.getOrNull()
}

package com.cocode.measureapp.ui

import android.content.Context
import android.hardware.camera2.CameraCharacteristics
import android.hardware.camera2.CameraManager
import android.view.Surface
import android.view.WindowManager
import com.cocode.measureapp.capture.IntrinsicsExtractor
import com.cocode.measureapp.geometry.CameraIntrinsics

/** Current display rotation in degrees (0/90/180/270) — keeps the tilt level orientation-aware. */
@Suppress("DEPRECATION")
internal fun displayRotationDegrees(context: Context): Int =
    when ((context.getSystemService(Context.WINDOW_SERVICE) as WindowManager).defaultDisplay.rotation) {
        Surface.ROTATION_90 -> 90
        Surface.ROTATION_180 -> 180
        Surface.ROTATION_270 -> 270
        else -> 0
    }

/** Reads camera intrinsics from the bound camera, falling back to the first back-facing camera. */
internal fun readIntrinsics(context: Context, boundId: String?, w: Int, h: Int): CameraIntrinsics {
    val cm = context.getSystemService(Context.CAMERA_SERVICE) as CameraManager
    if (boundId != null) return IntrinsicsExtractor.extract(cm.getCameraCharacteristics(boundId), w, h)
    val id = cm.cameraIdList.firstOrNull {
        cm.getCameraCharacteristics(it).get(CameraCharacteristics.LENS_FACING) ==
            CameraCharacteristics.LENS_FACING_BACK
    } ?: cm.cameraIdList.firstOrNull()
    return if (id != null) IntrinsicsExtractor.extract(cm.getCameraCharacteristics(id), w, h)
    else { val f = maxOf(w, h).toDouble(); CameraIntrinsics(f, f, w / 2.0, h / 2.0) }
}
