import androidx.activity.compose.BackHandler
import androidx.compose.foundation.layout.Box
import androidx.compose.foundation.layout.fillMaxSize
import androidx.compose.foundation.layout.safeDrawingPadding
import androidx.compose.material3.MaterialTheme
import androidx.compose.material3.Surface
import androidx.compose.runtime.Composable
import androidx.compose.runtime.LaunchedEffect
import androidx.compose.runtime.collectAsState
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.rememberCoroutineScope
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.platform.LocalContext
import com.cocode.measureapp.core.LengthUnit
import com.cocode.measureapp.core.MeasurementSession
import com.cocode.measureapp.core.MeasurementView
import com.cocode.measureapp.data.SettingsRepository
import com.cocode.measureapp.detect.OpenCvStickDetector
import com.cocode.measureapp.export.AnnotatedExporter
import com.cocode.measureapp.geometry.Vec2
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

private enum class Step { Capture, Mark, Results, Settings, Help }

/** Top-level flow: capture -> mark -> results, with settings + help side-screens. */
@Composable
fun MeasureApp() {
    val context = LocalContext.current
    val repo     = remember { SettingsRepository(context.applicationContext) }
    val detector = remember { OpenCvStickDetector() }
    val scope    = rememberCoroutineScope()
    val stickLength by repo.stickLengthMeters.collectAsState(initial = SettingsRepository.DEFAULT_LENGTH_M)
    val stickWidth  by repo.stickWidthMeters.collectAsState(initial = SettingsRepository.DEFAULT_WIDTH_M)
    val unit        by repo.unit.collectAsState(initial = LengthUnit.METERS)

    var step     by remember { mutableStateOf(Step.Capture) }
    var captured by remember { mutableStateOf<CapturedImage?>(null) }
    var view     by remember { mutableStateOf<MeasurementView?>(null) }
    var session  by remember { mutableStateOf(MeasurementSession()) }
    // Marking placements live here so they survive Mark <-> Results navigation.
    var savedCorners by remember { mutableStateOf<List<Vec2>?>(null) }
    var savedStick   by remember { mutableStateOf<List<Vec2>?>(null) }

    // System back steps through the flow instead of leaving the app.
    BackHandler(enabled = step != Step.Capture) {
        step = if (step == Step.Results) Step.Mark else Step.Capture
    }

    Surface(Modifier.fillMaxSize(), color = MaterialTheme.colorScheme.background) {
        Box(Modifier.fillMaxSize().safeDrawingPadding()) {
            when (step) {
                Step.Capture -> CameraScreen(
                    onCaptured = { img ->
                        captured = img
                        // New image revision: the shared node-05 invalidation drops any old result.
                        session = session.invalidate(); view = null
                        savedCorners = null; savedStick = null   // fresh marking for a new photo
                        step = Step.Mark
                    },
                    onSettings = { step = Step.Settings },
                    onHelp     = { step = Step.Help },
                )

                Step.Help -> HelpScreen(onBack = { step = Step.Capture })

                Step.Mark -> {
                    val img = captured
                    if (img == null) {
                        LaunchedEffect(Unit) { step = Step.Capture }
                    } else {
                        MarkScreen(
                            image            = img,
                            stickLengthMeters = stickLength,
                            stickWidthMeters  = stickWidth,
                            unit             = unit,
                            initialCorners   = savedCorners,
                            initialStick     = savedStick,
                            onMarkChanged    = { c, s -> savedCorners = c; savedStick = s },
                            detector         = detector,
                            onMeasured       = { v -> view = v; step = Step.Results },
                            onBack           = { step = Step.Capture },
                        )
                    }
                }

                Step.Results -> {
                    val v   = view
                    val img = captured
                    if (v == null) {
                        LaunchedEffect(Unit) { step = Step.Capture }
                    } else {
                        ResultsScreen(
                            view     = v,
                            onExport = {
                                if (img != null) scope.launch(Dispatchers.IO) {
                                    AnnotatedExporter.shareAnnotated(context, img.bitmap, v)
                                }
                            },
                            onRemark = { step = Step.Mark },
                            onDone   = { step = Step.Capture },
                        )
                    }
                }

                Step.Settings -> SettingsScreen(
                    stickLengthMeters = stickLength,
                    stickWidthMeters  = stickWidth,
                    unit     = unit,
                    onLength = { value -> scope.launch { repo.setStickLengthMeters(value) } },
                    onWidth  = { value -> scope.launch { repo.setStickWidthMeters(value) } },
                    onUnit   = { value -> scope.launch { repo.setUnit(value) } },
                    onBack   = { step = Step.Capture },
                )
            }
        }
    }
}

package com.cocode.measureapp.capture

import android.content.Context
import android.hardware.Sensor
import android.hardware.SensorEvent
import android.hardware.SensorEventListener
import android.hardware.SensorManager
import com.cocode.measureapp.capture.gravity.GravitySample
import com.cocode.measureapp.capture.gravity.GravitySampleDecoder
import com.cocode.measureapp.capture.gravity.GravitySampleHistory
import com.cocode.measureapp.capture.gravity.portraitCameraDownOrNull
import com.cocode.measureapp.geometry.Vec3

/**
 * Thin Android adapter over `TYPE_GRAVITY`. Each event is decoded by
 * [GravitySampleDecoder] into physical down in DEVICE axes (x right, y natural top,
 * z out of the screen) with its original `elapsedRealtimeNanos` event timestamp.
 * Missing sensor, no sample yet and invalid vectors are explicit [GravitySample.Unavailable].
 */
class GravityProvider(context: Context) : SensorEventListener {
    private val sensorManager = context.getSystemService(Context.SENSOR_SERVICE) as SensorManager
    private val sensor: Sensor? = sensorManager.getDefaultSensor(Sensor.TYPE_GRAVITY)
    private val history = GravitySampleHistory(sensorPresent = sensor != null)

    fun start() {
        sensor?.let { sensorManager.registerListener(this, it, SensorManager.SENSOR_DELAY_UI) }
    }

    fun stop() {
        sensorManager.unregisterListener(this)
    }

    /** Latest reading: physical down in device axes, or why it is unavailable. */
    fun latestSample(): GravitySample = history.latest

    /** Recent valid samples, oldest first, for matching against an exposure timestamp. */
    fun recentSamples(): List<GravitySample.Available> = history.snapshot()

    /**
     * Legacy capture bridge (upright-portrait back-camera approximation, sign-corrected).
     * Node 02 must replace this with its device-to-image transform over [latestSample].
     * The upright placeholder for unavailable data remains only because the current engine
     * API requires a non-null vector; [latestSample] never reports it as a reading.
     */
    @Deprecated("Use latestSample() and the capture-frame transform (node 02).")
    fun current(): Vec3 = history.latest.portraitCameraDownOrNull() ?: Vec3(0.0, 1.0, 0.0)

    override fun onSensorChanged(event: SensorEvent) {
        history.record(GravitySampleDecoder.decode(event.values, event.timestamp))
    }

    override fun onAccuracyChanged(sensor: Sensor?, accuracy: Int) {}
}

package com.cocode.measureapp.capture.gravity

import com.cocode.measureapp.geometry.Vec3

/** Clock domain of a sensor timestamp. Android sensor events use `elapsedRealtimeNanos`. */
enum class SensorClock { ELAPSED_REALTIME_NANOS }

/** Why no physical-down vector is available. None of these may be shown as "level". */
enum class GravityUnavailableReason { NO_SENSOR, NO_SAMPLE_YET, INVALID_VECTOR }

/**
 * One gravity reading, decoded into physical direction but NOT into a camera frame.
 *
 * Device axes: x toward the natural right edge, y toward the phone's natural top,
 * z out of the screen. Converting to camera/image axes (node 02) or display/view axes
 * (level overlay) is the consumer's job; neither may invert the direction again.
 */
sealed interface GravitySample {
    /**
     * [down] is a finite unit vector along physical down in device axes. [timestampNanos]
     * is the original sensor-event time (not callback receipt) in [clock].
     */
    data class Available(
        val down: Vec3,
        val timestampNanos: Long,
        val clock: SensorClock = SensorClock.ELAPSED_REALTIME_NANOS,
    ) : GravitySample

    data class Unavailable(val reason: GravityUnavailableReason) : GravitySample
}

/** Decodes raw `TYPE_GRAVITY` values; pure Kotlin so the adapter's exact math is unit-tested. */
object GravitySampleDecoder {
    /** Below this magnitude (m/s^2) a reading carries no usable direction. */
    const val MIN_MAGNITUDE = 1e-6

    /**
     * Android reports the stationary acceleration reaction, which points physically UP:
     * an upright phone reads `(0, +g, 0)`. Physical down is therefore the negated,
     * normalized sample: `(0, -1, 0)` for that upright phone.
     */
    fun decode(values: FloatArray, timestampNanos: Long): GravitySample {
        if (values.size < 3) return invalid()
        val x = values[0].toDouble(); val y = values[1].toDouble(); val z = values[2].toDouble()
        if (!x.isFinite() || !y.isFinite() || !z.isFinite()) return invalid()
        val up = Vec3(x, y, z)
        val n = up.norm()
        if (!n.isFinite() || n < MIN_MAGNITUDE) return invalid()
        return GravitySample.Available(up * (-1.0 / n), timestampNanos)
    }

    /** Initial state before any sensor callback: absent sensor vs. not-yet-delivered. */
    fun initial(sensorPresent: Boolean): GravitySample = GravitySample.Unavailable(
        if (sensorPresent) GravityUnavailableReason.NO_SAMPLE_YET else GravityUnavailableReason.NO_SENSOR,
    )

    private fun invalid() = GravitySample.Unavailable(GravityUnavailableReason.INVALID_VECTOR)
}

/**
 * Legacy bridge for the capture path until node 02 applies the real device-to-image
 * transform: back camera held in upright natural portrait, camera axes x-right, y-down,
 * z-forward = `(dx, -dy, -dz)`. Returns null when no valid sample exists.
 */
fun GravitySample.portraitCameraDownOrNull(): Vec3? = when (this) {
    is GravitySample.Available -> Vec3(down.x, -down.y, -down.z)
    is GravitySample.Unavailable -> null
}

package com.cocode.measureapp.capture.recovery

/** Terminal outcome of one accepted capture request. */
sealed interface CaptureOutcome<out T> {
    data class Success<T>(val payload: T) : CaptureOutcome<T>
    data class Failure(val message: String, val cause: Throwable? = null) : CaptureOutcome<Nothing>
    data object Cancelled : CaptureOutcome<Nothing>
}

/** Observable capture state; [canCapture] is what enables the Capture button. */
data class CaptureState(
    val busy: Boolean = false,
    val error: String? = null,
    val disposed: Boolean = false,
) {
    fun canCapture(permissionGranted: Boolean, cameraReady: Boolean): Boolean =
        permissionGranted && cameraReady && !busy && !disposed
}

/**
 * Capture request lifecycle for one screen instance. Every accepted request ends in exactly
 * one [complete]; busy clears for success, failure and cancellation. Results for a superseded
 * request or a disposed screen are rejected and handed to [discard] so they don't leak.
 * A new screen instance (e.g. Retake) creates a new controller, so no busy flag is inherited.
 *
 * [requestIdOf] reads the shot identity carried by a payload; a success whose identity does
 * not match its request is a failure, so image and metadata never mix across requests.
 */
class CaptureController<T>(
    private val discard: (T) -> Unit = {},
    private val requestIdOf: (T) -> Int? = { null },
    private val onStateChanged: (CaptureState) -> Unit = {},
) {
    private var nextId = 0
    private var active: Int? = null
    private val inFlight = mutableSetOf<Int>()

    var state = CaptureState()
        private set(value) { field = value; onStateChanged(value) }

    /** True once disposed with no request still owed a callback: safe to release executors. */
    val released: Boolean
        @Synchronized get() = state.disposed && inFlight.isEmpty()

    /** Accepts a request, or returns null while one is active or after disposal. */
    @Synchronized
    fun begin(): Int? {
        if (state.busy || state.disposed) return null
        val id = ++nextId
        active = id
        inFlight += id
        state = state.copy(busy = true, error = null)
        return id
    }

    /**
     * Begins a request and runs [start] with its id. A synchronous throw from [start] completes
     * the request as a failure (no success is fabricated). Returns the id, or null if refused.
     */
    fun launch(start: (Int) -> Unit): Int? {
        val id = begin() ?: return null
        try {
            start(id)
        } catch (e: Throwable) {
            complete(id, CaptureOutcome.Failure(START_FAILED, e))
        }
        return id
    }

    /**
     * Records the terminal outcome for [id]. Returns the payload to deliver only for a
     * success of the active request on a live screen; everything else returns null.
     */
    @Synchronized
    fun complete(id: Int, outcome: CaptureOutcome<T>): T? {
        val owed = inFlight.remove(id)
        if (!owed || state.disposed || id != active) {
            if (outcome is CaptureOutcome.Success) discard(outcome.payload)
            return null
        }
        active = null
        return when (outcome) {
            is CaptureOutcome.Success -> {
                val shot = requestIdOf(outcome.payload)
                if (shot != null && shot != id) {
                    discard(outcome.payload)
                    state = state.copy(busy = false, error = MISMATCHED)
                    null
                } else {
                    state = state.copy(busy = false, error = null)
                    outcome.payload
                }
            }
            is CaptureOutcome.Failure -> { state = state.copy(busy = false, error = outcome.message); null }
            CaptureOutcome.Cancelled -> { state = state.copy(busy = false); null }
        }
    }

    /** The owning screen left: later results are ignored and discarded. */
    @Synchronized
    fun dispose() {
        active = null
        state = state.copy(busy = false, disposed = true)
    }

    companion object {
        const val START_FAILED = "Could not start the capture. Try again."
        const val MISMATCHED = "Captured photo did not match its request. Try again."
    }
}

package com.cocode.measureapp.capture.recovery

/** User-facing message for a frame that arrived but could not be converted or described. */
const val CONVERSION_FAILED = "Could not read the captured photo. Try again."

/**
 * Converts an acquired [frame] (an `ImageProxy` on Android) and always closes it, whether
 * [convert] succeeds or throws. [convert] must copy every piece of metadata it needs from the
 * frame before returning. Any throw becomes a [CaptureOutcome.Failure], never a partial success.
 */
fun <T> consumeFrame(frame: AutoCloseable, convert: () -> T): CaptureOutcome<T> =
    try {
        CaptureOutcome.Success(convert())
    } catch (e: Throwable) {
        CaptureOutcome.Failure(CONVERSION_FAILED, e)
    } finally {
        runCatching { frame.close() }
    }

package com.cocode.measureapp.capture.recovery

import com.cocode.measureapp.capture.gravity.GravitySample

/** The camera's declared clock for exposure timestamps (`SENSOR_INFO_TIMESTAMP_SOURCE`). */
enum class TimestampSource { REALTIME, UNKNOWN }

/** Exposure time of one shot, or why it is unavailable. Never substituted by callback time. */
sealed interface ExposureTimestamp {
    data class Available(val nanos: Long, val source: TimestampSource) : ExposureTimestamp
    data class Unavailable(val reason: String) : ExposureTimestamp
}

/** Whether intrinsics come from the device's lens calibration or an approximation. */
enum class CalibrationQuality { DEVICE_CALIBRATED, APPROXIMATE }

/** Crop rectangle in frame pixels, copied out of the proxy (no Android `Rect`). */
data class CropRect(val left: Int, val top: Int, val right: Int, val bottom: Int) {
    val width: Int get() = right - left
    val height: Int get() = bottom - top

    fun isNonEmptyWithin(frameWidth: Int, frameHeight: Int): Boolean =
        left >= 0 && top >= 0 && width > 0 && height > 0 && right <= frameWidth && bottom <= frameHeight
}

/**
 * Metadata identifying one shot, copied before its proxy is closed. [requestId] ties it to
 * the image delivered with it. [gravity] and [recentGravity] are the raw samples at copy
 * time; matching them to [exposure] and transforming to the image frame belongs to node 02.
 */
data class CaptureMetadata(
    val requestId: Int,
    val frameWidth: Int,
    val frameHeight: Int,
    val rotationDegrees: Int,
    val crop: CropRect,
    val exposure: ExposureTimestamp,
    val gravity: GravitySample,
    val recentGravity: List<GravitySample.Available>,
    val calibration: CalibrationQuality,
) {
    /**
     * Throws [IncompleteCaptureException] when required fields cannot describe an image of
     * [imageWidth] x [imageHeight]. Optional data (timestamp, gravity) is flagged, not required.
     */
    fun requireComplete(imageWidth: Int, imageHeight: Int) {
        if (imageWidth <= 0 || imageHeight <= 0) incomplete("empty image ${imageWidth}x$imageHeight")
        if (frameWidth <= 0 || frameHeight <= 0) incomplete("empty frame ${frameWidth}x$frameHeight")
        if (rotationDegrees !in VALID_ROTATIONS) incomplete("rotation $rotationDegrees")
        if (!crop.isNonEmptyWithin(frameWidth, frameHeight)) incomplete("crop $crop")
    }

    private fun incomplete(what: String): Nothing = throw IncompleteCaptureException(what)

    companion object {
        val VALID_ROTATIONS = setOf(0, 90, 180, 270)
    }
}

/** A capture whose image/metadata handoff is incomplete; a failure, never a partial success. */
class IncompleteCaptureException(what: String) : IllegalStateException("Incomplete capture metadata: $what")

/** Camera2 `SENSOR_INFO_TIMESTAMP_SOURCE_*` values, mirrored so this stays Android-free. */
const val TIMESTAMP_SOURCE_UNKNOWN = 0
const val TIMESTAMP_SOURCE_REALTIME = 1

/**
 * Maps the proxy's exposure time and the camera's declared source. A non-positive time or
 * a missing/unrecognised declaration is explicit unavailability, not a guess.
 */
fun exposureTimestampOf(frameTimestampNanos: Long, declaredSource: Int?): ExposureTimestamp = when {
    frameTimestampNanos <= 0L -> ExposureTimestamp.Unavailable("frame has no exposure timestamp")
    declaredSource == TIMESTAMP_SOURCE_REALTIME ->
        ExposureTimestamp.Available(frameTimestampNanos, TimestampSource.REALTIME)
    declaredSource == TIMESTAMP_SOURCE_UNKNOWN ->
        ExposureTimestamp.Available(frameTimestampNanos, TimestampSource.UNKNOWN)
    declaredSource == null -> ExposureTimestamp.Unavailable("camera timestamp source undeclared")
    else -> ExposureTimestamp.Unavailable("unrecognised timestamp source $declaredSource")
}

